<?php $title='Payments';require __DIR__.'/../includes/header.php';require_login('admin');require __DIR__.'/../config/database.php';$rows=$pdo->query("SELECT p.*,u.name customer,s.name category FROM payments p JOIN users u ON u.id=p.customer_id JOIN assistance_requests r ON r.id=p.request_id JOIN service_categories s ON s.id=r.category_id ORDER BY p.created_at DESC")->fetchAll();?>
<section class="section-pad"><div class="container"><h1 class="fw-bold mb-4">Transactions</h1><div class="card border-0 shadow-sm rounded-4 p-3"><div class="table-responsive"><table class="table"><thead><tr><th>Reference</th><th>Customer</th><th>Service</th><th>Amount</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['transaction_reference'])?></td><td><?=e($r['customer'])?></td><td><?=e($r['category'])?></td><td>Rs. <?=number_format($r['amount'],2)?></td><td><?=e($r['payment_status'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></tbody></table></div></div></div></section><?php require __DIR__.'/../includes/footer.php'; ?>